package com.networkers.eventfee;
import com.networkers.user.User;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"user_id","fee_year","fee_month"})) public class EventFee{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private User user;@Column(name="fee_year")private int year;@Column(name="fee_month")private int month;private BigDecimal amount=new BigDecimal("2100.00");@Enumerated(EnumType.STRING)private EventFeeStatus status=EventFeeStatus.UNPAID;private LocalDateTime paidAt;private LocalDate lastReminderDate;private LocalDateTime createdAt;
 @PrePersist void create(){createdAt=LocalDateTime.now();}public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public int getYear(){return year;}public void setYear(int v){year=v;}public int getMonth(){return month;}public void setMonth(int v){month=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public EventFeeStatus getStatus(){return status;}public void setStatus(EventFeeStatus v){status=v;paidAt=v==EventFeeStatus.PAID?LocalDateTime.now():null;}public LocalDateTime getPaidAt(){return paidAt;}public LocalDate getLastReminderDate(){return lastReminderDate;}public void setLastReminderDate(LocalDate v){lastReminderDate=v;}
}
